const cache = new InMemoryCache({
  typePolicies: {
    Query: {
      fields: {
        post: {
          read(_, { args, cache }) {
            return cache.readQuery({
              query: gql`
                query GetPost($id: ID!) {
                  post(id: $id) { id title author { name } }
                }
              `,
              variables: { id: args?.id },
            });
          },
        },
      },
    },
  },
});
